            const fileHeight = width < 480 ? 166 : width < 760 ? 146 : 114;
            // rc.118: estimates are a starting point; rows that render taller (long names, a theme's larger type, 130% text) are measured
            // and grown, and the measurement is remembered for the next redraw, so no row is cut off.
            if (!this.filesMeasuredHeights || this.filesMeasuredHeights.size > 20000) this.filesMeasuredHeights = new Map();
            const measureKeyOf = (e, i) => `${e.type === "file" ? NDU3.fileKeyString(e.f.key) + "|" + this.requirementExpanded.has(NDU3.fileKeyString(e.f.key)) + "|" + (this.requirementsReader.get(e.f)?.status || "") : "mod:" + (e.group?.id || i)}|${Math.round(width / 40)}|${scale}|${this.s.settings.theme}`;
