            host.style.position = "relative";
            host.tabIndex = -1;
            host.style.overflow = "auto";
            // Short collections should not occupy a full-height empty scroll panel.
            const totalHeight = offsets[offsets.length - 1];
            const maximumHeight = Math.min((window.innerHeight || 900) * .62, 620);
            host.style.height = `${Math.min(totalHeight, maximumHeight)}px`;
