            this.modalRoot.querySelectorAll("[data-files-guide-section]").forEach(link => link.addEventListener("click", NDU3.openInstallationGuide));
            this.modalRoot.querySelector("#closeFileDetails")?.addEventListener("click", () => { this.hideModal(); if (opener?.isConnected) opener.focus({ preventScroll: true }); });
