            this.contentRoot.querySelector("#overallProgress").style.setProperty("--p", `${percent}%`);
            this.contentRoot.querySelector("#runOverallTrack").setAttribute("aria-valuenow", String(percent));
            this.contentRoot.querySelector("#metricActive").textContent = String(groups.active.length);
