(function (NDU3) {
    async function main() {
        if (typeof document === "undefined")
            return;
        try {
            const app = await NDU3.bootstrapApplication();
            // Capture the site's actual rendered Requirements accordion on mod pages.
            // Other open NDU tabs receive the bounded names-only cache via GM storage.
            app.ui.requirementsReader.watchRenderedPage(app.nexus.context());
            const open = () => app.ui.open();
            try {
                if (typeof GM !== "undefined" && typeof GM.registerMenuCommand === "function")
                    GM.registerMenuCommand("Open Nexus Downloader Ultimate", open);
                else if (typeof GM_registerMenuCommand === "function")
                    GM_registerMenuCommand("Open Nexus Downloader Ultimate", open);
            }
            catch { }
            globalThis.NDU3 = Object.freeze({ identity: NDU3.IDENTITY, app, api: NDU3.TEST_API });
        }
        catch (error) {
            console.error(`[${NDU3.IDENTITY.name}] bootstrap failed`, error);
        }
    }
    if (typeof globalThis !== "undefined") {
        globalThis.NDU3 = Object.freeze({ identity: NDU3.IDENTITY, createFoundation: NDU3.createFoundation, api: NDU3.TEST_API });
    }
    if (typeof document !== "undefined") {
        if (document.readyState === "loading")
            document.addEventListener("DOMContentLoaded", () => void main(), { once: true });
        else
            void main();
    }
})(NDU3 || (NDU3 = {}));
